if n <= 0:
        raise ValueError("n must be a positive integer")

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        limit = int(num ** 0.5) + 1
        for div in range(3, limit, 2):
            if num % div == 0:
                return False
        return True

    count = 0
    a, b = 0, 1  # Fibonacci starters F0=0, F1=1
    while True:
        a, b = b, a + b  # advance to next Fibonacci number
        if is_prime(a):
            count += 1
            if count == n:
                return a
